final_template:
AWSTemplateFormatVersion: '2010-09-09'
Description: >-
  Provisions an AWS IoT Core device-onboarding policy through a Lambda-backed
  custom resource (Node.js 24.x). The policy allows devices to connect, publish,
  subscribe and receive only on topics scoped to their own thing name.

Resources:
  IoTPolicyFunctionRole:
    Type: AWS::IAM::Role
    Properties:
      AssumeRolePolicyDocument:
        Version: '2012-10-17'
        Statement:
          - Effect: Allow
            Principal:
              Service: lambda.amazonaws.com
            Action: sts:AssumeRole
      ManagedPolicyArns:
        - !Sub 'arn:${AWS::Partition}:iam::aws:policy/service-role/AWSLambdaBasicExecutionRole'
      Policies:
        - PolicyName: IoTPolicyManagement
          PolicyDocument:
            Version: '2012-10-17'
            Statement:
              - Sid: ManageIoTPolicies
                Effect: Allow
                Action:
                  - iot:CreatePolicy
                  - iot:CreatePolicyVersion
                  - iot:DeletePolicy
                  - iot:DeletePolicyVersion
                  - iot:GetPolicy
                  - iot:ListPolicyVersions
                  - iot:ListTargetsForPolicy
                Resource:
                  - !Sub 'arn:${AWS::Partition}:iot:${AWS::Region}:${AWS::AccountId}:policy/*'
              - Sid: DetachIoTPolicies
                Effect: Allow
                Action:
                  - iot:DetachPolicy
                Resource:
                  - !Sub 'arn:${AWS::Partition}:iot:${AWS::Region}:${AWS::AccountId}:cert/*'
                  - !Sub 'arn:${AWS::Partition}:iot:${AWS::Region}:${AWS::AccountId}:thinggroup/*'
                  - !Sub 'arn:${AWS::Partition}:iot:${AWS::Region}:${AWS::AccountId}:policy/*'

  IoTPolicyFunction:
    Type: AWS::Lambda::Function
    Properties:
      Description: Custom resource handler that manages an AWS IoT Core device-onboarding policy.
      Runtime: nodejs24.x
      Handler: index.handler
      Role: !GetAtt IoTPolicyFunctionRole.Arn
      Timeout: 120
      MemorySize: 256
      Code:
        ZipFile: |
          const {
            IoTClient, CreatePolicyCommand, CreatePolicyVersionCommand,
            ListPolicyVersionsCommand, DeletePolicyVersionCommand,
            ListTargetsForPolicyCommand, DetachPolicyCommand, DeletePolicyCommand
          } = require('@aws-sdk/client-iot');

          const iot = new IoTClient({});

          const respond = async (e, status, reason, id, data) => {
            const body = JSON.stringify({
              Status: status,
              Reason: reason,
              PhysicalResourceId: id,
              StackId: e.StackId,
              RequestId: e.RequestId,
              LogicalResourceId: e.LogicalResourceId,
              Data: data
            });
            const res = await fetch(e.ResponseURL, {
              method: 'PUT',
              headers: { 'Content-Type': '' },
              body
            });
            console.log('CloudFormation response status:', res.status);
          };

          const sanitize = (n) => String(n).replace(/[^\w+=,.@-]/g, '-').slice(0, 128);

          const buildDocument = (region, account) => {
            const p = `arn:aws:iot:${region}:${account}`;
            const t = '${iot:Connection.Thing.ThingName}';
            return JSON.stringify({
              Version: '2012-10-17',
              Statement: [
                {
                  Effect: 'Allow',
                  Action: 'iot:Connect',
                  Resource: p + ':client/' + t,
                  Condition: { Bool: { 'iot:Connection.Thing.IsAttached': 'true' } }
                },
                { Effect: 'Allow', Action: 'iot:Publish', Resource: p + ':topic/devices/' + t + '/*' },
                { Effect: 'Allow', Action: 'iot:Subscribe', Resource: p + ':topicfilter/devices/' + t + '/*' },
                { Effect: 'Allow', Action: 'iot:Receive', Resource: p + ':topic/devices/' + t + '/*' }
              ]
            });
          };

          const listVersions = async (name) =>
            (await iot.send(new ListPolicyVersionsCommand({ policyName: name }))).policyVersions || [];

          const deletePolicy = async (name) => {
            try {
              let marker;
              do {
                const r = await iot.send(new ListTargetsForPolicyCommand({ policyName: name, marker, pageSize: 250 }));
                for (const target of r.targets || []) {
                  await iot.send(new DetachPolicyCommand({ policyName: name, target }));
                }
                marker = r.nextMarker;
              } while (marker);
              for (const v of await listVersions(name)) {
                if (!v.isDefaultVersion) {
                  await iot.send(new DeletePolicyVersionCommand({ policyName: name, policyVersionId: v.versionId }));
                }
              }
              await iot.send(new DeletePolicyCommand({ policyName: name }));
            } catch (err) {
              if (err.name !== 'ResourceNotFoundException') throw err;
              console.log('Policy not found, treating delete as success:', name);
            }
          };

          exports.handler = async (e) => {
            console.log('Event:', JSON.stringify({ ...e, ResponseURL: '[redacted]' }));
            let id = e.PhysicalResourceId;
            try {
              const props = e.ResourceProperties;
              const name = sanitize(props.PolicyName);
              const arn = `arn:aws:iot:${props.Region}:${props.AccountId}:policy/${name}`;
              const doc = buildDocument(props.Region, props.AccountId);
              let data = {};

              if (e.RequestType === 'Delete') {
                await deletePolicy(id);
              } else if (e.RequestType === 'Create' || id !== name) {
                const r = await iot.send(new CreatePolicyCommand({ policyName: name, policyDocument: doc }));
                id = name;
                data = { PolicyName: name, PolicyArn: r.policyArn || arn };
              } else {
                const versions = await listVersions(name);
                if (versions.length >= 5) {
                  const oldest = versions
                    .filter((v) => !v.isDefaultVersion)
                    .sort((a, b) => new Date(a.createDate) - new Date(b.createDate))[0];
                  await iot.send(new DeletePolicyVersionCommand({ policyName: name, policyVersionId: oldest.versionId }));
                }
                await iot.send(new CreatePolicyVersionCommand({ policyName: name, policyDocument: doc, setAsDefault: true }));
                data = { PolicyName: name, PolicyArn: arn };
              }

              await respond(e, 'SUCCESS', 'OK', id, data);
            } catch (err) {
              console.error(err);
              await respond(e, 'FAILED', String(err.message || err).slice(0, 1000), id || 'failed-' + e.RequestId, {});
            }
          };

  IoTPolicyFunctionLogGroup:
    Type: AWS::Logs::LogGroup
    Properties:
      LogGroupName: !Sub '/aws/lambda/${IoTPolicyFunction}'
      RetentionInDays: 14

  DeviceOnboardingPolicy:
    Type: Custom::IoTPolicy
    Properties:
      ServiceToken: !GetAtt IoTPolicyFunction.Arn
      PolicyName: !Sub '${AWS::StackName}-DeviceOnboardingPolicy'
      Region: !Ref AWS::Region
      AccountId: !Ref AWS::AccountId

Outputs:
  PolicyName:
    Description: Name of the generated AWS IoT Core device-onboarding policy.
    Value: !GetAtt DeviceOnboardingPolicy.PolicyName
    Export:
      Name: !Sub '${AWS::StackName}-IoTPolicyName'
  PolicyArn:
    Description: ARN of the generated AWS IoT Core device-onboarding policy.
    Value: !GetAtt DeviceOnboardingPolicy.PolicyArn
    Export:
      Name: !Sub '${AWS::StackName}-IoTPolicyArn'

AWSTemplateFormatVersion: '2010-09-09'
Description: Self-contained AWS AppSync GraphQL Todo API (TodoAPIwithJs) with API key authentication, a DynamoDB backend with a byOwner GSI, JavaScript pipeline resolvers for CRUD and query-by-owner operations, and real-time subscriptions.

Resources:
  TodoTable:
    Type: AWS::DynamoDB::Table
    DeletionPolicy: Retain
    UpdateReplacePolicy: Retain
    Properties:
      BillingMode: PAY_PER_REQUEST
      AttributeDefinitions:
        - AttributeName: id
          AttributeType: S
        - AttributeName: owner
          AttributeType: S
      KeySchema:
        - AttributeName: id
          KeyType: HASH
      GlobalSecondaryIndexes:
        - IndexName: byOwner
          KeySchema:
            - AttributeName: owner
              KeyType: HASH
          Projection:
            ProjectionType: ALL
      SSESpecification:
        SSEEnabled: true
      PointInTimeRecoverySpecification:
        PointInTimeRecoveryEnabled: true
      Tags:
        - Key: Application
          Value: TodoAPIwithJs

  AppSyncDynamoDBRole:
    Type: AWS::IAM::Role
    Properties:
      Description: Allows AppSync to access the Todo DynamoDB table and its indexes
      AssumeRolePolicyDocument:
        Version: '2012-10-17'
        Statement:
          - Effect: Allow
            Principal:
              Service: appsync.amazonaws.com
            Action: sts:AssumeRole
      Policies:
        - PolicyName: TodoTableAccess
          PolicyDocument:
            Version: '2012-10-17'
            Statement:
              - Effect: Allow
                Action:
                  - dynamodb:GetItem
                  - dynamodb:PutItem
                  - dynamodb:UpdateItem
                  - dynamodb:DeleteItem
                  - dynamodb:Scan
                  - dynamodb:Query
                Resource:
                  - !GetAtt TodoTable.Arn
                  - !Sub '${TodoTable.Arn}/index/*'

  AppSyncLoggingRole:
    Type: AWS::IAM::Role
    Properties:
      Description: Allows AppSync to push logs to CloudWatch Logs
      AssumeRolePolicyDocument:
        Version: '2012-10-17'
        Statement:
          - Effect: Allow
            Principal:
              Service: appsync.amazonaws.com
            Action: sts:AssumeRole
      ManagedPolicyArns:
        - !Sub 'arn:${AWS::Partition}:iam::aws:policy/service-role/AWSAppSyncPushToCloudWatchLogs'

  TodoApi:
    Type: AWS::AppSync::GraphQLApi
    Properties:
      Name: TodoAPIwithJs
      AuthenticationType: API_KEY
      XrayEnabled: true
      LogConfig:
        CloudWatchLogsRoleArn: !GetAtt AppSyncLoggingRole.Arn
        FieldLogLevel: ERROR
        ExcludeVerboseContent: true
      Tags:
        - Key: Application
          Value: TodoAPIwithJs

  TodoApiLogGroup:
    Type: AWS::Logs::LogGroup
    DeletionPolicy: Delete
    UpdateReplacePolicy: Delete
    Properties:
      LogGroupName: !Sub '/aws/appsync/apis/${TodoApi.ApiId}'
      RetentionInDays: 30

  TodoApiKey:
    Type: AWS::AppSync::ApiKey
    Properties:
      ApiId: !GetAtt TodoApi.ApiId
      Description: API key for the TodoAPIwithJs GraphQL API

  TodoSchema:
    Type: AWS::AppSync::GraphQLSchema
    Properties:
      ApiId: !GetAtt TodoApi.ApiId
      Definition: |
        type Todo {
          id: ID!
          title: String!
          description: String
          owner: String!
          completed: Boolean
          createdAt: AWSDateTime
          updatedAt: AWSDateTime
        }

        type TodoConnection {
          items: [Todo]
          nextToken: String
        }

        input CreateTodoInput {
          title: String!
          description: String
          owner: String!
          completed: Boolean
        }

        input UpdateTodoInput {
          id: ID!
          title: String
          description: String
          owner: String
          completed: Boolean
        }

        input DeleteTodoInput {
          id: ID!
        }

        type Query {
          getTodo(id: ID!): Todo
          listTodos(limit: Int, nextToken: String): TodoConnection
          listTodosByOwner(owner: String!, limit: Int, nextToken: String): TodoConnection
        }

        type Mutation {
          createTodo(input: CreateTodoInput!): Todo
          updateTodo(input: UpdateTodoInput!): Todo
          deleteTodo(input: DeleteTodoInput!): Todo
        }

        type Subscription {
          onCreateTodo: Todo
            @aws_subscribe(mutations: ["createTodo"])
          onUpdateTodo: Todo
            @aws_subscribe(mutations: ["updateTodo"])
          onDeleteTodo: Todo
            @aws_subscribe(mutations: ["deleteTodo"])
        }

        schema {
          query: Query
          mutation: Mutation
          subscription: Subscription
        }

  TodoDataSource:
    Type: AWS::AppSync::DataSource
    Properties:
      ApiId: !GetAtt TodoApi.ApiId
      Name: TodoTableDataSource
      Description: DynamoDB data source for the Todo table
      Type: AMAZON_DYNAMODB
      ServiceRoleArn: !GetAtt AppSyncDynamoDBRole.Arn
      DynamoDBConfig:
        TableName: !Ref TodoTable
        AwsRegion: !Ref AWS::Region

  CreateTodoFunction:
    Type: AWS::AppSync::FunctionConfiguration
    Properties:
      ApiId: !GetAtt TodoApi.ApiId
      Name: CreateTodoFunction
      Description: Creates a new Todo item
      DataSourceName: !GetAtt TodoDataSource.Name
      Runtime:
        Name: APPSYNC_JS
        RuntimeVersion: 1.0.0
      Code: |
        import { util } from '@aws-appsync/utils';

        export function request(ctx) {
          const id = util.autoId();
          const now = util.time.nowISO8601();
          const values = { ...ctx.args.input, createdAt: now, updatedAt: now };
          if (values.completed === undefined || values.completed === null) {
            values.completed = false;
          }
          return {
            operation: 'PutItem',
            key: util.dynamodb.toMapValues({ id: id }),
            attributeValues: util.dynamodb.toMapValues(values),
            condition: { expression: 'attribute_not_exists(id)' }
          };
        }

        export function response(ctx) {
          if (ctx.error) {
            util.error(ctx.error.message, ctx.error.type);
          }
          return ctx.result;
        }

  GetTodoFunction:
    Type: AWS::AppSync::FunctionConfiguration
    Properties:
      ApiId: !GetAtt TodoApi.ApiId
      Name: GetTodoFunction
      Description: Retrieves a single Todo item by id
      DataSourceName: !GetAtt TodoDataSource.Name
      Runtime:
        Name: APPSYNC_JS
        RuntimeVersion: 1.0.0
      Code: |
        import { util } from '@aws-appsync/utils';

        export function request(ctx) {
          return {
            operation: 'GetItem',
            key: util.dynamodb.toMapValues({ id: ctx.args.id })
          };
        }

        export function response(ctx) {
          if (ctx.error) {
            util.error(ctx.error.message, ctx.error.type);
          }
          return ctx.result;
        }

  UpdateTodoFunction:
    Type: AWS::AppSync::FunctionConfiguration
    Properties:
      ApiId: !GetAtt TodoApi.ApiId
      Name: UpdateTodoFunction
      Description: Updates an existing Todo item
      DataSourceName: !GetAtt TodoDataSource.Name
      Runtime:
        Name: APPSYNC_JS
        RuntimeVersion: 1.0.0
      Code: |
        import { util } from '@aws-appsync/utils';

        export function request(ctx) {
          const { id, ...values } = ctx.args.input;
          values.updatedAt = util.time.nowISO8601();

          const setExpressions = [];
          const expressionNames = {};
          const expressionValues = {};

          for (const [key, value] of Object.entries(values)) {
            if (value !== undefined && value !== null) {
              setExpressions.push('#' + key + ' = :' + key);
              expressionNames['#' + key] = key;
              expressionValues[':' + key] = value;
            }
          }

          return {
            operation: 'UpdateItem',
            key: util.dynamodb.toMapValues({ id: id }),
            update: {
              expression: 'SET ' + setExpressions.join(', '),
              expressionNames: expressionNames,
              expressionValues: util.dynamodb.toMapValues(expressionValues)
            },
            condition: { expression: 'attribute_exists(id)' }
          };
        }

        export function response(ctx) {
          if (ctx.error) {
            util.error(ctx.error.message, ctx.error.type);
          }
          return ctx.result;
        }

  DeleteTodoFunction:
    Type: AWS::AppSync::FunctionConfiguration
    Properties:
      ApiId: !GetAtt TodoApi.ApiId
      Name: DeleteTodoFunction
      Description: Deletes a Todo item and returns the deleted item
      DataSourceName: !GetAtt TodoDataSource.Name
      Runtime:
        Name: APPSYNC_JS
        RuntimeVersion: 1.0.0
      Code: |
        import { util } from '@aws-appsync/utils';

        export function request(ctx) {
          return {
            operation: 'DeleteItem',
            key: util.dynamodb.toMapValues({ id: ctx.args.input.id }),
            condition: { expression: 'attribute_exists(id)' }
          };
        }

        export function response(ctx) {
          if (ctx.error) {
            util.error(ctx.error.message, ctx.error.type);
          }
          return ctx.result;
        }

  ListTodosFunction:
    Type: AWS::AppSync::FunctionConfiguration
    Properties:
      ApiId: !GetAtt TodoApi.ApiId
      Name: ListTodosFunction
      Description: Lists Todo items with pagination
      DataSourceName: !GetAtt TodoDataSource.Name
      Runtime:
        Name: APPSYNC_JS
        RuntimeVersion: 1.0.0
      Code: |
        import { util } from '@aws-appsync/utils';

        export function request(ctx) {
          const request = {
            operation: 'Scan',
            limit: ctx.args.limit ? ctx.args.limit : 20
          };
          if (ctx.args.nextToken) {
            request.nextToken = ctx.args.nextToken;
          }
          return request;
        }

        export function response(ctx) {
          if (ctx.error) {
            util.error(ctx.error.message, ctx.error.type);
          }
          return { items: ctx.result.items, nextToken: ctx.result.nextToken };
        }

  ListTodosByOwnerFunction:
    Type: AWS::AppSync::FunctionConfiguration
    Properties:
      ApiId: !GetAtt TodoApi.ApiId
      Name: ListTodosByOwnerFunction
      Description: Lists Todo items for an owner using the byOwner index
      DataSourceName: !GetAtt TodoDataSource.Name
      Runtime:
        Name: APPSYNC_JS
        RuntimeVersion: 1.0.0
      Code: |
        import { util } from '@aws-appsync/utils';

        export function request(ctx) {
          const request = {
            operation: 'Query',
            index: 'byOwner',
            query: {
              expression: '#owner = :owner',
              expressionNames: { '#owner': 'owner' },
              expressionValues: util.dynamodb.toMapValues({ ':owner': ctx.args.owner })
            },
            limit: ctx.args.limit ? ctx.args.limit : 20
          };
          if (ctx.args.nextToken) {
            request.nextToken = ctx.args.nextToken;
          }
          return request;
        }

        export function response(ctx) {
          if (ctx.error) {
            util.error(ctx.error.message, ctx.error.type);
          }
          return { items: ctx.result.items, nextToken: ctx.result.nextToken };
        }

  CreateTodoResolver:
    Type: AWS::AppSync::Resolver
    DependsOn: TodoSchema
    Properties:
      ApiId: !GetAtt TodoApi.ApiId
      TypeName: Mutation
      FieldName: createTodo
      Kind: PIPELINE
      PipelineConfig:
        Functions:
          - !GetAtt CreateTodoFunction.FunctionId
      Runtime:
        Name: APPSYNC_JS
        RuntimeVersion: 1.0.0
      Code: |
        export function request(ctx) {
          return {};
        }

        export function response(ctx) {
          return ctx.prev.result;
        }

  GetTodoResolver:
    Type: AWS::AppSync::Resolver
    DependsOn: TodoSchema
    Properties:
      ApiId: !GetAtt TodoApi.ApiId
      TypeName: Query
      FieldName: getTodo
      Kind: PIPELINE
      PipelineConfig:
        Functions:
          - !GetAtt GetTodoFunction.FunctionId
      Runtime:
        Name: APPSYNC_JS
        RuntimeVersion: 1.0.0
      Code: |
        export function request(ctx) {
          return {};
        }

        export function response(ctx) {
          return ctx.prev.result;
        }

  UpdateTodoResolver:
    Type: AWS::AppSync::Resolver
    DependsOn: TodoSchema
    Properties:
      ApiId: !GetAtt TodoApi.ApiId
      TypeName: Mutation
      FieldName: updateTodo
      Kind: PIPELINE
      PipelineConfig:
        Functions:
          - !GetAtt UpdateTodoFunction.FunctionId
      Runtime:
        Name: APPSYNC_JS
        RuntimeVersion: 1.0.0
      Code: |
        export function request(ctx) {
          return {};
        }

        export function response(ctx) {
          return ctx.prev.result;
        }

  DeleteTodoResolver:
    Type: AWS::AppSync::Resolver
    DependsOn: TodoSchema
    Properties:
      ApiId: !GetAtt TodoApi.ApiId
      TypeName: Mutation
      FieldName: deleteTodo
      Kind: PIPELINE
      PipelineConfig:
        Functions:
          - !GetAtt DeleteTodoFunction.FunctionId
      Runtime:
        Name: APPSYNC_JS
        RuntimeVersion: 1.0.0
      Code: |
        export function request(ctx) {
          return {};
        }

        export function response(ctx) {
          return ctx.prev.result;
        }

  ListTodosResolver:
    Type: AWS::AppSync::Resolver
    DependsOn: TodoSchema
    Properties:
      ApiId: !GetAtt TodoApi.ApiId
      TypeName: Query
      FieldName: listTodos
      Kind: PIPELINE
      PipelineConfig:
        Functions:
          - !GetAtt ListTodosFunction.FunctionId
      Runtime:
        Name: APPSYNC_JS
        RuntimeVersion: 1.0.0
      Code: |
        export function request(ctx) {
          return {};
        }

        export function response(ctx) {
          return ctx.prev.result;
        }

  ListTodosByOwnerResolver:
    Type: AWS::AppSync::Resolver
    DependsOn: TodoSchema
    Properties:
      ApiId: !GetAtt TodoApi.ApiId
      TypeName: Query
      FieldName: listTodosByOwner
      Kind: PIPELINE
      PipelineConfig:
        Functions:
          - !GetAtt ListTodosByOwnerFunction.FunctionId
      Runtime:
        Name: APPSYNC_JS
        RuntimeVersion: 1.0.0
      Code: |
        export function request(ctx) {
          return {};
        }

        export function response(ctx) {
          return ctx.prev.result;
        }

Outputs:
  GraphQLApiId:
    Description: AppSync GraphQL API ID
    Value: !GetAtt TodoApi.ApiId
  GraphQLApiUrl:
    Description: AppSync GraphQL endpoint URL
    Value: !GetAtt TodoApi.GraphQLUrl
  GraphQLApiRealtimeUrl:
    Description: AppSync real-time (subscriptions) endpoint URL
    Value: !GetAtt TodoApi.RealtimeUrl
  GraphQLApiArn:
    Description: AppSync GraphQL API ARN
    Value: !GetAtt TodoApi.Arn
  GraphQLApiKey:
    Description: API key for the AppSync GraphQL API
    Value: !GetAtt TodoApiKey.ApiKey
  TodoTableName:
    Description: Name of the DynamoDB Todo table
    Value: !Ref TodoTable
  TodoTableArn:
    Description: ARN of the DynamoDB Todo table
    Value: !GetAtt TodoTable.Arn
